#!/usr/bin/env python3
"""Embed the original JPEG bytes. Run again after replacing a bundled image."""
from pathlib import Path
import argparse
import hashlib


ASSETS = (
    ("StarEyes", "6AECCD18E30048EFC2946A824BD6E089.jpg"),
    ("Bubbles", "8A88047E005ECCFAACF29438427A3B14.jpg"),
    ("BlueButterfly", "EA68D70D6F5E4CCF0854725F5ABE4048.jpg"),
)


def generate():
    root = Path(__file__).resolve().parent
    lines = [
        "#pragma once",
        "// Generated by assets/backdrops/generate_presets.py; do not edit by hand.",
        "// Original JPEG files are embedded without recompression or cropping.",
        '#include "SpatialBackdropPresets.h"',
        "#include <cstddef>",
        "namespace spatial_backdrop_presets {",
        "struct EncodedImage {const unsigned char* bytes;std::size_t size;};",
        "namespace data {",
    ]
    for symbol, filename in ASSETS:
        encoded = (root / filename).read_bytes()
        if not encoded.startswith(b"\xff\xd8\xff") or not encoded.endswith(b"\xff\xd9"):
            raise ValueError(f"Expected a complete JPEG: {filename}")
        lines.append(f"// {filename}; {len(encoded)} bytes; SHA256 {hashlib.sha256(encoded).hexdigest()}")
        lines.append(f"alignas(4) inline constexpr unsigned char {symbol}[]={{")
        for offset in range(0, len(encoded), 20):
            lines.append("    " + ",".join(f"0x{value:02x}" for value in encoded[offset:offset + 20]) + ",")
        lines.append("};")
    lines.extend(["} // namespace data", "inline EncodedImage Get(int index){", "    switch(index){"])
    for index, (symbol, _) in enumerate(ASSETS):
        lines.append(f"    case {index}:return {{data::{symbol},sizeof(data::{symbol})}};")
    lines.extend([
        "    default:return {nullptr,0};",
        "    }",
        "}",
        "} // namespace spatial_backdrop_presets",
        "",
    ])
    return (root.parents[1] / "src" / "SpatialBackdropPresetData.h", "\n".join(lines).encode("utf-8"))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Verify the checked-in header without writing it")
    args = parser.parse_args()
    output, content = generate()
    if args.check:
        if not output.is_file() or output.read_bytes() != content:
            raise SystemExit(f"Outdated generated resource: {output}")
        print(f"PASS embedded backgrounds match original JPEG files: {output}")
    else:
        output.write_bytes(content)
        print(f"Generated {output} ({len(content)} bytes)")


if __name__ == "__main__":
    main()
